"use strict";

// The NEGATIVE control that makes RWF-022 sound rather than merely
// conservative. Every heritage value here is VALID, so every class
// definition completes and `module.exports = safeOp` really is reached on
// every load. Withdrawing authority from any of these would be a FALSE
// REFUSAL -- the failure mode a value classifier is most exposed to.
//
// Proven in-process, with assertions, in the ground-truth fixture's `c.js`.

function dangerousOp(input) {
  return "EXPLODED:" + input;
}

function safeOp(input) {
  return "safe:" + input;
}

// Definitely constructable: a class.
function makeBase() {
  return class Base {};
}

// Definitely constructable: an ordinary function.
function makeCtor() {
  return function Ctor() {};
}

// `extends null` is LEGAL. Classifying this as invalid would be the single
// worst available mistake, so it is a control in its own right.
function makeNull() {
  return null;
}

// Two returns, one of them invalid: not definitely anything.
function maybeBase(flag) {
  if (flag) {
    return makeBase();
  }
  return 1;
}

// Returns 1, but the class is DEFERRED inside a function nobody calls at
// module scope, so its heritage never runs at module-evaluation time.
function notAConstructor() {
  return 1;
}

function configure() {
  class Deferred extends notAConstructor() {}
  return Deferred;
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;

  class FromClass extends makeBase() {}
  class FromFunction extends makeCtor() {}
  class FromNull extends makeNull() {}
  class FromMaybe extends maybeBase(true) {}

  void FromClass;
  void FromFunction;
  void FromNull;
  void FromMaybe;
  void configure;
}

module.exports = safeOp;
